CREATE TABLE IF NOT EXISTS sys_user(id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE,password_hash VARCHAR(100) NOT NULL,display_name VARCHAR(100) NOT NULL,status INT NOT NULL,created_at TIMESTAMP NOT NULL,updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS sys_role(id BIGINT AUTO_INCREMENT PRIMARY KEY,role_code VARCHAR(30) UNIQUE NOT NULL,role_name VARCHAR(50) NOT NULL,description VARCHAR(255));
CREATE TABLE IF NOT EXISTS sys_user_role(id BIGINT AUTO_INCREMENT PRIMARY KEY,user_id BIGINT NOT NULL,role_id BIGINT NOT NULL,UNIQUE(user_id,role_id),FOREIGN KEY(user_id) REFERENCES sys_user(id),FOREIGN KEY(role_id) REFERENCES sys_role(id));
MERGE INTO sys_role(id,role_code,role_name) KEY(id) VALUES(1,'ADMIN','管理员'),(2,'EDITOR','剪辑人员'),(3,'REVIEWER','审核人员');
